if (ctx.results[0].aggregations == null) return false;

def hostBuckets = ctx.results[0].aggregations.group_by_hostname.buckets;
for (host in hostBuckets) {
  def sqlstateBuckets = host.group_by_sqlstate.buckets;
  for (sqlstate in sqlstateBuckets) {
    if (sqlstate.doc_count > 5) {
      return true;
    }
  }
}
return false;
